    return { r, error: "not settled in the dataset" };
  const steps = reqs.filter((q) => q.path === "/hilo2/action" && q.status === 200);
  const decisions = (final.events || []).map((e) => e.type === "skip" ? "skip" : e.side);
  if (final.outcome === "cashout")
    decisions.push("cashout");
